// Extract text content from HTML
const html = $input.first().json.body || $input.first().json.data;
const url = $('Capture All Inputs').item.json.productUrl;

// Remove script and style tags
let cleanText = html.replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, '');
cleanText = cleanText.replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, '');

// Remove HTML tags
cleanText = cleanText.replace(/<[^>]+>/g, ' ');

// Clean up whitespace
cleanText = cleanText.replace(/\s+/g, ' ').trim();

// Extract domain name for context
const domain = new URL(url).hostname.replace('www.', '');

return {
  productUrl: url,
  domain: domain,
  rawText: cleanText.substring(0, 50000), // Limit to first 50k chars
  scriptCount: $('Capture All Inputs').item.json.scriptCount,
  scriptLength: $('Capture All Inputs').item.json.scriptLength,
  selectedAngles: $('Capture All Inputs').item.json.selectedAngles
};

// Create array of items for script generation loop
const scriptCount = $input.first().json.scriptCount;
const items = [];

const wordCountMap = {
  '30s': 75,
  '60s': 150,
  '90s': 225,
  '120s': 300
};

const targetWordCount = wordCountMap[$input.first().json.scriptLength] || 150;

for (let i = 1; i <= scriptCount; i++) {
  items.push({
    scriptNumber: i,
    totalScripts: scriptCount,
    researchDocument: $input.first().json.researchDocument,
    scriptLength: $input.first().json.scriptLength,
    targetWordCount: targetWordCount,
    selectedAngles: $input.first().json.selectedAngles
  });
}

return items;

// Aggregate all outputs
const allScripts = $input.all();
const researchDoc = $('Prepare for Script Generation').item.json.researchDocument;
const productUrl = $('Capture All Inputs').item.json.productUrl;
const scriptLength = $('Capture All Inputs').item.json.scriptLength;

let finalDocument = `# PRODUCT RESEARCH & UGC SCRIPTS\n\n`;
finalDocument += `**Product URL:** ${productUrl}\n`;
finalDocument += `**Generated:** ${new Date().toISOString()}\n`;
finalDocument += `**Script Count:** ${allScripts.length}\n`;
finalDocument += `**Script Length:** ${scriptLength}\n\n`;
finalDocument += `${'='.repeat(80)}\n\n`;

// Add research document
finalDocument += `# PRODUCT RESEARCH DOCUMENT\n\n`;
finalDocument += researchDoc + '\n\n';
finalDocument += `${'='.repeat(80)}\n\n`;

// Add all scripts
finalDocument += `# UGC SCRIPTS\n\n`;
allScripts.forEach((item, index) => {
  finalDocument += item.json.scriptContent + '\n\n';
  if (index < allScripts.length - 1) {
    finalDocument += `${'─'.repeat(80)}\n\n`;
  }
});

return {
  finalDocument: finalDocument,
  researchDocument: researchDoc,
  productUrl: productUrl,
  scriptCount: allScripts.length,
  scriptLength: scriptLength,
  scripts: allScripts.map(item => ({
    number: item.json.scriptNumber,
    content: item.json.scriptContent
  }))
};
